-- Passage rg7-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('29de25e5-8e0c-5c59-bb0a-315239eaa221', 'rg7-theme-summary-p02', (select id from public.skills where slug = 'read-g7-theme-summary'), null,
        '6-8', $q$Low Tide$q$, $q$The first time, I ran the whole beach.
I wanted shells, and I wanted them fast.
I filled my pockets with broken white pieces.
I saw only sand and water rushing past.

My aunt sat down beside one gray rock.
She did not move for a long, slow while.
I kicked at the foam and asked her why.
She pointed down and gave a small smile.

A crab no bigger than my thumb
stepped sideways from a curtain of weed.
A starfish curled one orange arm.
A snail crept on at its own slow speed.

Then sea grass parted, and a tiny fish
flashed silver once and slipped from view.
The pool had been alive all along.
It only waited until I was still too.

This time I sit beside the rock.
My pockets stay as light as air.
I watch the water, and I wait,
and the whole small world is waiting there.$q$, 'draft')
