-- Passage rg7-theme-summary-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('6a36ddd6-d4a4-5460-81b9-8556965530dd', 'rg7-theme-summary-p05', (select id from public.skills where slug = 'read-g7-theme-summary'), null,
        '6-8', $q$The Results Page$q$, $q$For six weeks, Soo-ah had been sure that classical music would help bean plants grow taller. She had read about the idea online, and it sounded right. She set up two trays in her garage, one beside a small speaker and one in silence, and measured every plant each morning.

On the last day of the experiment, she lined up her data table and frowned. The plants in the quiet tray were slightly taller. Not by much, but they were taller.

"Maybe I measured wrong," she told her older brother, Min-jun. "I could just do it again. Or I could leave out the first week. The music tray was in a colder spot that week anyway."

Min-jun looked at her notebook. "Was it colder?"

Soo-ah hesitated. She had written down the temperature every day. Both trays had been the same.

She thought about the science fair judges reading a poster that proved her idea right. Then she thought about another student somewhere, reading her poster and believing something that was not true.

That night, she wrote a new title across the top of her poster board: "Music Did Not Help My Bean Plants Grow." Under "Conclusion," she explained that her results did not support her hypothesis. She also listed what she would change in a second test, like using more plants.

At the fair, a judge stopped at her table longer than at any other. "Most students show me what they hoped would happen," the judge said. "You showed me what actually happened. That is what scientists do."

Soo-ah did not win first place. She went home with an honorable mention and a list of new questions she wanted to test.$q$, 'draft')
