  ('91fd9e26-b439-5b7f-baf4-4c6d176c60fc', null, (select id from public.skills where slug = 'read-g7-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the passage?$q$, $q$[{"text":"Sunflowers are the best subject for a large outdoor mural.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Listening to others can make creative work richer and more meaningful.","is_correct":true},{"text":"Old photographs are more important than new paintings.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Young artists should never change their first ideas.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$Listening to others can make creative work richer and more meaningful.$q$, $q$Ana's mural becomes something the whole neighborhood loves only after she studies their ideas and history. She does change her first design, so the story argues against never changing.$q$, 'draft', 'b9773cda-55f8-5d1a-b2c5-5eea801b38f8')
